"""One-time scaffold for the final five independent apps. Refuses overwrites."""
from pathlib import Path
from datetime import datetime, timezone, timedelta
import importlib.util, json, shutil

ROOT=Path(__file__).resolve().parent.parent
APPS=[
 ('islamic-civilization-timeline','Islamic Civilization Timeline','Explore connected histories across regions, with dates and evidence in view.','blue','24 institutional-source records, regional map and filters, overlapping date bands, comparison, bookmarks and event pages.','A chronological rail with regional labels, a local land map and two-event comparison.','events','event','Historical periods and monuments are selected examples, not a complete history or religious endorsement of a dynasty. Preserve date ranges and institutional attribution.'),
 ('halal-business-decisions','Halal Business Decisions','Work through fictional business dilemmas, then inspect the choices and sources.','teal','12 fictional two-stage cases about disclosure, contracts, fair measures, payment and trust. Branch-specific consequences, source readings and optional recovery.','A decision ledger separates known facts, a choice and its fictional consequence.','cases','case','Educational applied reasoning does not constitute a scholarly ruling or opinion from quran.ai, quran.com or quran.foundation. No personalized legal or financial advice.'),
 ('revelation-context-explorer','Revelation Context Explorer','Read a passage beside the reports, and distinguish an occasion from its wider context.','blue','10 selected readings with attributed Bukhari reports, reliability and coverage notes, two fetched commentaries, relationship checks, bookmarks and print views.','A source dossier places the report beside what it establishes and what remains uncertain.','readings','reading','A transmitted occasion, general context and a response after revelation are distinct. Inclusion in Sahih al-Bukhari is a collection attribution, not a new independent grading of every claim.'),
 ('family-islamic-learning-challenges','Family Islamic Learning Challenges','Choose a short pack, gather around, and learn something together.','violet','12 single-sitting packs, each with a reading question, discussion and shared activity. Age/topic/type filters, print, optional recovery and completion sharing.','A three-card session path keeps a reading, conversation and practical activity together.','packs','pack','Suggested age bands are editorial reading guidance, not developmental assessments. Collect no names, child profiles, private disclosures or ongoing progress history.'),
 ('islamic-misinformation-casebook','Islamic Misinformation Casebook','Inspect a claim, open the evidence, and decide what the sources support.','teal','12 bounded reading claims with evidence cards, classification checks, precise corrections, source links, bookmarks and citation-rich sharing.','An evidence checklist comes before the conclusion, with explicit limits beside each source.','cases','case','Claims are constructed source-reading exercises, not measured viral trends or allegations against people. A report omitting a detail does not prove that no other source mentions it. No live fact-checking of arbitrary claims.'),
]
seed=ROOT/'apps/quran-concept-atlas'
spec=importlib.util.spec_from_file_location('context_methods',ROOT/'_implementation/populate-context.py')
methods=importlib.util.module_from_spec(spec);spec.loader.exec_module(methods)
stamp=datetime.now(timezone.utc).astimezone(timezone(timedelta(hours=6))).isoformat(timespec='seconds')
for index,(slug,name,description,accent,scope,signature,key,route,boundary) in enumerate(APPS):
 app=ROOT/'apps'/slug
 assert not app.exists(),f'Refusing to overwrite {app}'
 for directory in ['src/pages','src/layouts','src/lib','src/data','src/styles','src/components','tests','public/fonts','context']:(app/directory).mkdir(parents=True)
 for file in ['astro.config.mjs','tsconfig.json','LICENSE','public/favicon.svg','public/_headers','public/robots.txt','src/pages/privacy.astro','src/pages/404.astro','src/layouts/Shell.astro','src/lib/utils.ts','src/lib/shell.ts','src/styles/global.css','tests/storage.test.ts']:
  shutil.copyfile(seed/file,app/file)
 for font in (seed/'public/fonts').iterdir():shutil.copyfile(font,app/'public/fonts'/font.name)
 package=json.loads((seed/'package.json').read_text(encoding='utf-8'));package['name']=slug
 for command in ['dev','preview']:package['scripts'][command]=package['scripts'][command].replace('4328',str(4336+index))
 (app/'package.json').write_text(json.dumps(package,indent=2)+'\n',encoding='utf-8')
 (app/'src/data/config.json').write_text(json.dumps(dict(slug=slug,name=name,description=description,accent=accent,port=4336+index),indent=2)+'\n',encoding='utf-8')
 (app/'AGENTS.md').write_text(methods.agent_text(name,True),encoding='utf-8')
 docs={
  'project-overview.md':f'''# {name}\n\n{description}\n\n## Authorized scope\n\nPortfolio rank {16+index}. Independent project `apps/{slug}`. {scope}\n\n## Visitor flow\n\nChoose an entry with the catalog filters, open its activity, inspect the sources, then optionally save or share. Every core interaction works without storage or an account.\n\n## Content limits\n\n{boundary}\n\n## Success criteria\n\nAll entries have complete detail pages and working interactions. Quran quotations match the canonical snapshot. Both themes, narrow layouts, blocked storage, meaningful logic tests, Astro check and static builds must pass before completion. Hosting publication is outside this request.\n''',
  'architecture.md':f'''# Architecture: {name}\n\n## Stack\n\nAstro 7.4.2, TypeScript 6.0.3, @astrojs/check 0.9.12 and Bun 1.4.4. Native Astro/HTML/CSS and browser TypeScript; no UI framework, server adapter, auth or database.\n\n## Ownership\n\n`src/pages/index.astro` owns discovery. `src/pages/{route}/[id].astro` publishes each `{key}` entry with getStaticPaths. `src/components/` owns reusable reading/reference/filter markup. `src/layouts/Shell.astro` owns metadata and theme/privacy controls. `src/lib/` owns local interactions and validated activity logic. `src/data/` keeps bundled content, source records and checksum provenance. `public/` contains local fonts and security headers.\n\n## State and deployment\n\nUse in-memory interaction state. Explicit bookmarks or opt-in recovery use `{slug}:<key>` and validated timestamp envelopes, ignored after 30 days. Theme is separate from activity opt-in. Clear-data removes this namespace. Port {4336+index}; build `bun install --frozen-lockfile && bun run build`, output `dist`, BUN_VERSION=1.4.4. Publish at its own domain root, without Functions, bindings or secrets.\n\n## Invariants\n\nPreserve independent builds, local runtime assets, literal canonical quotations, attribution and storage resilience. {boundary}\n\nResearch/QA live in repository `_implementation/research/batch4/` and `_implementation/qa/batch4/`. Ordinary app builds do not import repository tooling.\n''',
  'ui-context.md':methods.ui_text(name,accent,signature),
  'code-standards.md':methods.common_standards(True),
  'ai-workflow-rules.md':methods.workflow_text(slug,4336+index,regression=f'Check all {key} detail routes, catalog filters and empty results, source links, core activity completion, retries/reset, explicit sharing, both themes, keyboard navigation and blocked/expired storage. {boundary}'),
  'progress-tracker.md':f'''# Progress: {name}\n\nLast updated: {stamp} Asia/Dhaka.\n\n## Current goal\n\nImplement the user-authorized final shortlist batch, including this filled context set.\n\n## Completed\n\nConfirmed rank, feature boundary, static architecture, pinned packages, local font/theme conventions and source retrieval methods. Created independent configuration, shell and context files.\n\n## In progress\n\nSource preparation, app-specific content and interactions. No check, test, build, browser or hosting completion is claimed yet.\n\n## Next up\n\nImplement the activity and meaningful tests, install its independent lockfile, run Astro check/build and browser/static verification, then package `release/{slug}-pages.zip`.\n\n## Open questions\n\nNone block the authorized implementation. Hosting account/domain selection is outside this request.\n\n## Decisions and evidence\n\nOfficial Quran MCP provides canonical data and selected commentaries. Context7 `/withastro/docs` confirms static routes/client scripts; Cloudflare documentation MCP confirms static output requires no SSR adapter. Preserve report and institutional source attribution. {boundary}\n''',
 }
 for file,text in docs.items():(app/'context'/file).write_text(text,encoding='utf-8')
 (app/'README.md').write_text(f'''# {name}\n\n{description}\n\nIndependent Astro 7.4.2 / Bun 1.4.4 project.\n\n```sh\nbun install --frozen-lockfile\nbun run dev\nbun run check\nbun test\nbun run build\nbun run preview\n```\n\nPort {4336+index}. Cloudflare Pages project root `apps/{slug}`, output `dist`, build `bun install --frozen-lockfile && bun run build`, environment `BUN_VERSION=1.4.4`. Host at the domain root. No adapter, secrets, backend or live content API.\n\n{scope}\n\n{boundary}\n\nRead AGENTS.md and context/ before implementation. Sources and privacy pages explain content editions, reuse and temporary optional localStorage. Release ZIPs are produced at repository level.\n''',encoding='utf-8')
 print(slug)
